    name: 'Muzharul Islam',
    alternativeNames: ['Mazharul Islam', 'Muzharul Islam Chowdhury'],
    gender: 'man',
    born: 1923,
    died: 2012,
    floruit: { start: 1955, end: 1990, override: false },
    movements: [{ id: 'tropical-modernism', primary: true }, { id: 'brutalism', primary: false }],
